            "easy1_desc": "연구진은 대형 언어 모델 에이전트를 키울 때 쓰는 기존 방식인 에이전트 강화학습이 비용이 많이 들고 보상이 드물게 들어와서 시험 시간에 적용하기 어렵다는 점을 짚어봤습니다. 쉽게 말하면, 정답을 찾는 과정이 너무 벅차고 피드백이 늦게 와서 효율이 떨어진다는 말이에요.",
