            "easy1_desc": "스트레스를 알아내려고 심전도 신호(ECG)를 쓸 때 딥러닝 기술이 많이 쓰였는데요, 지금까지는 한 가지 종류의 특징만 보는 경우가 많았다는 거예요. 그러다 보니 심전도 신호에 담긴 모양새와 시간에 따라 변하는 모습을 한꺼번에 담아내는 데 한계가 있었다는 말이에요. 쉽게 말하면, 반쪽짜리 정보만 보고 스트레스를 판정하려 했던 셈이에요.",
